#!/usr/bin/env python3
"""Preview installations at the production central gateway (HOR-661, DES-HOR-661-09).

Every PR preview and staging is an `internal` (company-funded) installation of
the production central gateway. The deploy registers it (idempotent) and issues
its client certificate; teardown and the reaper revoke it. All calls go through
the commit's own `forge central` with the ambient CI preview role, which
central's operator allow-list scopes to internal `pr-*`/`staging`
installations. The installation's private key is generated by Forge and only
ever travels inside the Secret manifest piped to the preview host's kubectl.

Until central is applied, CENTRAL_URL and CENTRAL_CA_BUNDLE are both unset:
previews then deploy with no managed model and revocation is a no-op (founder,
2026-10-14). HOR-661 acceptance re-requires central once it is applied.
"""
from __future__ import annotations

import argparse
import os
import pathlib
import re
import subprocess
import sys
from collections.abc import Mapping, Sequence

ROOT = pathlib.Path(__file__).resolve().parents[2]
NAME = re.compile(r"pr-[1-9][0-9]*|staging")
SECRET_NAME = "iterabase-central-client"
GO_FORGE = ("go", "run", "./forge/cmd/forge")


class CentralError(RuntimeError):
    """A central operator call failed or its inputs are missing."""


def configured(env: Mapping[str, str] = os.environ) -> bool:
    """Whether central is configured for previews. Both repository variables
    unset means central is not applied yet; one without the other is an error."""
    url = env.get("CENTRAL_URL", "").strip()
    ca = env.get("CENTRAL_CA_BUNDLE", "").strip()
    if not url and not ca:
        return False
    settings(env)
    return True


def settings(env: Mapping[str, str] = os.environ) -> tuple[str, str]:
    """The central URL and CA bundle from the CENTRAL_URL / CENTRAL_CA_BUNDLE
    repository variables. There is no fallback inference path."""
    url = env.get("CENTRAL_URL", "").strip()
    ca = env.get("CENTRAL_CA_BUNDLE", "").strip()
    if not re.fullmatch(r"https://[a-z0-9.-]+(:[0-9]+)?/?", url):
        raise CentralError("set the CENTRAL_URL repository variable to the central gateway URL "
                           "(e.g. https://central.iterabase.com); previews route managed inference through it")
    if "-----BEGIN CERTIFICATE-----" not in ca or "-----END CERTIFICATE-----" not in ca:
        raise CentralError("set the CENTRAL_CA_BUNDLE repository variable to the central CA certificate PEM "
                           "(docs/runbooks/central-gateway.md)")
    return url.rstrip("/"), ca + "\n"


def require_name(name: str) -> str:
    if not NAME.fullmatch(name):
        raise CentralError(f"not a preview installation name: {name!r} (expected pr-<number> or staging)")
    return name


class Central:
    """`forge central` against the production central gateway."""

    def __init__(self, url: str, ca_path: pathlib.Path, forge: Sequence[str] = GO_FORGE) -> None:
        self.url, self.ca_path, self.forge = url, ca_path, tuple(forge)

    @classmethod
    def from_env(cls, workdir: pathlib.Path, forge: Sequence[str] = GO_FORGE,
                 env: Mapping[str, str] = os.environ) -> "Central":
        url, ca = settings(env)
        ca_path = workdir / "central-ca.crt"
        ca_path.write_text(ca, encoding="utf-8")
        return cls(url, ca_path, forge)

    def command(self, *args: str) -> list[str]:
        return [*self.forge, "central", *args, "--central-url", self.url, "--ca-bundle", str(self.ca_path)]

    def _run(self, *args: str) -> subprocess.CompletedProcess[str]:
        return subprocess.run(self.command(*args), cwd=ROOT, capture_output=True, text=True, check=False)

    def register(self, name: str) -> None:
        result = self._run("register", "--installation", require_name(name), "--deployment", "internal",
                           "--plan", "none", "--currency", "EUR")
        if result.returncode != 0:
            raise CentralError(f"central register {name} failed: {result.stderr.strip()}")

    def secret_manifest(self, name: str, namespace: str) -> str:
        """The installation's kubernetes.io/tls Secret. It holds the private key:
        callers pipe it straight to kubectl and never print or store it."""
        result = self._run("issue", "--installation", require_name(name), "--secret-manifest",
                           "--namespace", namespace, "--secret-name", SECRET_NAME)
        if result.returncode != 0:
            raise CentralError(f"central issue {name} failed: {result.stderr.strip()}")
        if "kind: Secret" not in result.stdout:
            raise CentralError(f"central issue {name} returned no Secret manifest")
        return result.stdout

    def revoke(self, name: str, reason: str) -> bool:
        """Revoke a preview installation; False when central never knew it."""
        result = self._run("revoke", "--installation", require_name(name), "--reason", reason)
        if result.returncode == 0:
            return True
        if "installation_not_found" in result.stderr:
            return False
        raise CentralError(f"central revoke {name} failed: {result.stderr.strip()}")


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    sub = parser.add_subparsers(dest="command", required=True)
    revoke = sub.add_parser("revoke", help="revoke preview installations (teardown, reaper)")
    revoke.add_argument("--installations", required=True, help="comma-separated pr-<n>/staging names; empty is a no-op")
    revoke.add_argument("--reason", required=True)
    revoke.add_argument("--workdir", default=os.environ.get("RUNNER_TEMP", "/tmp"))
    args = parser.parse_args(argv)
    names = [name.strip() for name in args.installations.split(",") if name.strip()]
    if not names:
        print("central: no preview installations to revoke")
        return 0
    try:
        if not configured():
            print("central: not configured (CENTRAL_URL unset); nothing to revoke")
            return 0
        central = Central.from_env(pathlib.Path(args.workdir))
        for name in names:
            known = central.revoke(name, args.reason)
            print(f"central: {'revoked' if known else 'never registered'} {name}")
    except CentralError as error:
        print(f"central: {error}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
